  4	/**
  5	 * Shared movement, feeding, and breeding behavior for foraging animals.
  6	 */
  7	public abstract class ForagingAnimal extends Animal
  8	{
  9	    private static final Random rand = Randomizer.getRandom();
 10	
 11	    // The amount of oxygen an animal need to survive
 12	    protected static final double ANIMAL_OXYGEN_REQUIRED = 0.0000009;
 13	
 14	    private final ForagingBehavior behavior;
 15	    // The age of the animal.
 16	    private int age;
 17	    // The animal's food level.
 18	    private int foodLevel;
 19	
 20	    protected ForagingAnimal(boolean randomAge, Field field, Location location)
 21	    {
 22	        super(field, location);
 23	        this.behavior = ForagingBehaviorFactory.forAnimal((Class<? extends ForagingAnimal>)getClass());
 24	        initializeLife(randomAge);
 25	    }
 26	
 27	    /**
 28	     * Initialize the shared age and hunger state for a concrete species.
 29	     * @param randomAge Whether the animal should start at a random age.
 30	     */
 31	    protected final void initializeLife(boolean randomAge)
 32	    {
 33	        if(randomAge) {
 34	            age = rand.nextInt(behavior.getMaxAge());
 35	            foodLevel = rand.nextInt(behavior.getFoodValue());
 36	        }
 37	        else {
 38	            age = 0;
 39	            foodLevel = behavior.getFoodValue();
 40	        }
 41	    }
 42	
 43	    /**
 44	     * @return The current age of the animal.
 45	     */
 46	    protected final int getAge()
 47	    {
 48	        return age;
 49	    }
 50	
 51	    /**
 52	     * @return The current food level of the animal.
 53	     */
 54	    protected final int getFoodLevel()
 55	    {
 56	        return foodLevel;
 57	    }
 58	
 59	    /**
 60	     * Set the current food level.
 61	     * @param foodValue The new food value.
 62	     */
 63	    protected final void setFoodLevel(int foodValue)
 64	    {
 65	        foodLevel = foodValue;
 66	    }
 67	
 68	    /**
 69	     * Increase age and kill the animal if it has exceeded its maximum age.
 70	     */
 71	    protected final void incrementAge()
 72	    {
 73	        age++;
 74	        if(age > behavior.getMaxAge()) {
 75	            setDead();
 76	        }
 77	    }
 78	
 79	    /**
 80	     * Decrease the current food level and kill the animal if it starves.
 81	     */
 82	    protected final void incrementHunger()
 83	    {
 84	        foodLevel--;
 85	        if(foodLevel <= 0) {
 86	            setDead();
 87	        }
 88	    }
 89	
 90	    /**
 91	     * Determine whether the animal is old enough to breed.
 92	     * @return true if the animal is old enough to breed.
 93	     */
 94	    protected final boolean isOldEnoughToBreed()
 95	    {
 96	        return age >= behavior.getBreedingAge();
 97	    }
 98	
 99	    /**
100	     * Search for prey, spread disease from infected nearby animals, and consume prey.
101	     * @param disease The disease model.
102	     * @param step The current simulation step.
103	     * @return The location of the prey if found, otherwise null.
104	     */
105	    public final Location search(Disease disease, int step)
106	    {
107	        Field field = getField();
108	        List<Location> adjacent = field.adjacentLocations(getLocation(), behavior.getSearchDistance());
109	        for(Location loc : adjacent) {
110	            Object creature = field.getObjectAt(loc);
111	            if(creature instanceof Animal) {
112	                Animal animal = (Animal)creature;
113	                if(animal.getIsInfected()) {
114	                    makeInfected(disease, step);
115	                }
116	            }
117	            if(isOneOf(creature, behavior.getPreyTypes())) {
118	                Creature prey = (Creature)creature;
119	                if(prey.isAlive()) {
120	                    prey.setDead();
121	                    setFoodLevel(behavior.getFoodValue());
122	                    return loc;
123	                }
124	            }
125	        }
126	        return null;
127	    }
128	
129	    /**
130	     * identify whether a creature need to sleep
131	     *
132	     * @param atDayTime true if it is at day time false if it is at night time.
133	     * @return true if currently it is night.
134	     */
135	    public boolean needSleep(boolean atDayTime)
136	    {
137	        return !atDayTime;
138	    }
139	
140	    /**
141	     * Run the standard animal life-cycle shared by foraging animals.
142	     * @param newCreatures A list to receive newborn creatures.
143	     * @param atDayTime true if current step is daytime false otherwise.
144	     * @param oxygenLevel The current oxygen level.
145	     * @param disease The disease model.
146	     * @param step The current simulation step.
147	     * @return The oxygen delta for this action.
148	     */
149	    public final double act(List<Creature> newCreatures, boolean atDayTime, double oxygenLevel, Disease disease, int step)
150	    {
151	        if(oxygenLevel < ANIMAL_OXYGEN_REQUIRED) {
152	            setDead();
153	            return 0;
154	        }
155	
156	        if(dieOfInfection(disease)) {
157	            return 0;
158	        }
159	
160	        ifCanGrantImmunity(disease, step);
161	        incrementAge();
162	        incrementHunger();
163	
164	        if(isAlive() && !needSleep(atDayTime)) {
165	            giveBirth(newCreatures);
166	            Location newLocation = search(disease, step);
167	            if(newLocation == null) {
168	                newLocation = getField().freeAdjacentLocation(getLocation());
169	            }
170	            if(newLocation != null) {
171	                setLocation(newLocation);
172	            }
173	            else {
174	                setDead();
175	            }
176	        }
177	
178	        return -ANIMAL_OXYGEN_REQUIRED;
179	    }
180	
181	    /**
182	     * Create a birth if breeding conditions are met.
183	     * @return Number of offspring to create.
184	     */
185	    protected final int breed()
186	    {
187	        int births = 0;
188	        if(canBreed() && rand.nextDouble() <= behavior.getBreedingProbability()) {
189	            births = rand.nextInt(behavior.getMaxLitterSize()) + 1;
190	        }
191	        return births;
192	    }
193	
194	    /**
195	     * Create offspring in adjacent free locations.
196	     * @param newCreatures A list to receive newborn creatures.
197	     */
198	    protected final void giveBirth(List<Creature> newCreatures)
199	    {
200	        Field field = getField();
201	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
202	        int births = breed();
203	        for(int b = 0; b < births && free.size() > 0; b++) {
204	            newCreatures.add(behavior.createOffspring(field, free.remove(0)));
205	        }
206	    }
207	
208	    /**
209	     * Determine whether this animal can currently breed.
210	     * @return true if breeding is allowed.
211	     */
212	    protected final boolean canBreed()
213	    {
214	        return isOldEnoughToBreed() && (!behavior.breedingRequiresMate() || hasOppositeSexMate(behavior.getMateSpecies(), behavior.getMateDistance()));
215	    }
216	
217	    /**
218	     * Check whether an object is one of the specified classes.
219	     * @param object The object to inspect.
220	     * @param classes The allowed classes.
221	     * @return true if the object matches one of the classes.
222	     */
223	    private boolean isOneOf(Object object, Class<?>... classes)
224	    {
225	        if(object == null) {
226	            return false;
227	        }
228	        for(Class<?> type : classes) {
229	            if(type.isInstance(object)) {
230	                return true;
231	            }
232	        }
233	        return false;
234	    }
235	
236	    /**
237	     * Determine whether there is an opposite-sex animal of the configured species nearby.
238	     * @return true if a mate is nearby.
239	     */
240	    private boolean hasOppositeSexMate(Class<? extends Animal> species, int adjacentDistance)
241	    {
242	        Field field = getField();
243	        List<Location> adjacent = field.adjacentLocations(getLocation(), adjacentDistance);
244	        for(Location where : adjacent) {
245	            Object occupant = field.getObjectAt(where);
246	            if(species.isInstance(occupant)) {
247	                Animal mate = (Animal)occupant;
248	                if(getSex() != mate.getSex()) {
249	                    return true;
250	                }
251	            }
252	        }
253	        return false;
254	    }
255	}

